import io.github.psd2live.core.Cmo3ModelImport;
import org.umamo.runtime.model.*;
import java.nio.file.*;
import java.util.*;
public class NeckCmoReadback {
 public static void main(String[] args) throws Exception {
  Path file=Path.of(args[0]);
  PuppetModel model=Cmo3ModelImport.INSTANCE.read(Files.readAllBytes(file)).getPuppet();
  if(model.getDrawables().size()!=1 || model.getParameters().size()!=3 || !model.getDeformers().isEmpty())throw new IllegalStateException("Incorrect editable CMO structure");
  Drawable d=model.getDrawables().getFirst();
  if(d.getMesh().getVertexCount()!=63 || d.getMesh().getTriangleCount()!=96 || d.getGeometryGrid().getAxes().size()!=3 || d.getGeometryGrid().getCells().size()!=27)throw new IllegalStateException("CMO lost dense mesh or geometry grid");
  Set<String> axes=new HashSet<>();
  for(var a:d.getGeometryGrid().getAxes()) {
   var getter=Arrays.stream(a.getClass().getMethods()).filter(m->m.getName().startsWith("getParameterId-")).findFirst().orElseThrow();
   axes.add((String)getter.invoke(a));
   if(a.getKeys().length!=3 || a.getKeys()[1]!=0)throw new IllegalStateException("CMO axes not neutral-centered");
  }
  if(!axes.equals(Set.of("ParamNeckBottomX","ParamNeckBottomY","ParamNeckCurve")))throw new IllegalStateException("CMO axes changed");
  for(var cell:d.getGeometryGrid().getCells()) {
   Object form=cell.getForm();
   var getter=form.getClass().getMethod("getPositionDeltas");
   if(((float[])getter.invoke(form)).length!=126)throw new IllegalStateException("CMO keyform has wrong topology");
  }
  System.out.println("{\"passed\":true,\"kind\":\"public_cmo3_readback\",\"parameters\":3,\"drawables\":1,\"deformers\":0,\"vertices\":63,\"triangles\":96,\"geometry_axes\":3,\"geometry_cells\":27,\"each_keyform_float_count\":126,\"visual_approval\":\"unreviewed\"}");
 }
}
